fragments:
fragment SetFragment on Set {
  id
  event {
    __typename
    ...EventFragment
    tournament {
      __typename
      ...TournamentFragment
    }
  }
  startAt
  slots {
    slotIndex
    entrant {
      team {
        __typename
        ...TeamFragment
      }
    }
  }
  games {
    winnerId
  }
  winnerId
  fullRoundText
  round
}
fragment TournamentFragment on Tournament {
  id
  name
  startAt
  endAt
  images {
    url
  }
  events {
    __typename
    ...EventFragment
  }
  hasOfflineEvents
  currency
}
fragment EventFragment on Event {
  id
  name
  startAt
  isOnline
}
fragment TeamFragment on Team {
  id
  name
  images {
    url
  }
}
